(function () {
  "use strict";

  // Texts and page URLs for this language, generated by website/build.ps1.
  var data = JSON.parse(document.getElementById("page-data").textContent);
  var STORAGE_KEY = "cs2clutchez.lang";

  function normalize(code) {
    if (!code) return null;
    code = String(code).toLowerCase();
    if (code.indexOf("pt") === 0) return "pt-BR";
    if (code.indexOf("es") === 0) return "es";
    if (code.indexOf("en") === 0) return "en";
    return null;
  }

  function stored() {
    try { return normalize(localStorage.getItem(STORAGE_KEY)); } catch (e) { return null; }
  }

  function remember(lang) {
    try { localStorage.setItem(STORAGE_KEY, lang); } catch (e) { /* private mode: the choice just isn't remembered */ }
  }

  function browserLanguage() {
    var prefs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language];
    for (var i = 0; i < prefs.length; i++) {
      var n = normalize(prefs[i]);
      if (n) return n;
    }
    return null;
  }

  var params = new URLSearchParams(location.search);

  // Links from the first version of the site (?lang=en) go to that language's page.
  var asked = normalize(params.get("lang"));
  if (asked && asked !== data.lang) {
    params.delete("lang");
    var query = params.toString();
    location.replace(data.pages[asked] + (query ? "?" + query : "") + location.hash);
    return;
  }

  document.querySelectorAll(".lang a").forEach(function (a) {
    a.addEventListener("click", function () { remember(a.getAttribute("hreflang")); });
  });

  // Suggest the visitor's language with a banner; never redirect on our own, so search engines see every page.
  var preferred = stored() || browserLanguage();
  if (preferred && preferred !== data.lang && data.banner[preferred]) {
    var b = data.banner[preferred];
    var bar = document.createElement("div");
    bar.className = "lang-banner";
    bar.setAttribute("lang", preferred);
    var text = document.createElement("span");
    text.textContent = b.text;
    var go = document.createElement("a");
    go.href = b.url + location.search + location.hash;
    go.textContent = b.action;
    go.addEventListener("click", function () { remember(preferred); });
    var close = document.createElement("button");
    close.type = "button";
    close.setAttribute("aria-label", b.close);
    close.textContent = "×";
    close.addEventListener("click", function () { remember(data.lang); bar.remove(); });
    bar.appendChild(text);
    bar.appendChild(go);
    bar.appendChild(close);
    document.body.insertBefore(bar, document.body.firstChild);
  }

  // Share code → cs2clutchez://CSGO-... (handled by the installed app). Accepts any text that contains a code,
  // e.g. a steam:// link copied from the game.
  var CODE = /CSGO(-[ABCDEFGHJKLMNOPQRSTUVWXYZabcdefhijkmnopqrstuvwxyz23456789]{5}){5}/;
  var form = document.getElementById("share-form");
  var input = document.getElementById("share-code");
  var hint = document.getElementById("share-hint");

  var preset = params.get("code") || decodeURIComponent(location.hash.slice(1));
  var presetMatch = preset && preset.match(CODE);
  if (presetMatch) input.value = presetMatch[0];

  function showHint(text, isError) {
    hint.textContent = text;
    hint.classList.toggle("error", isError);
    input.setAttribute("aria-invalid", String(isError));
  }

  input.addEventListener("input", function () {
    if (input.getAttribute("aria-invalid") === "true") {
      input.setAttribute("aria-invalid", "false");
      hint.classList.remove("error");
      hint.textContent = data.text.note;
    }
  });

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var match = input.value.match(CODE);
    if (!match) {
      showHint(data.text.invalid, true);
      input.focus();
      return;
    }
    input.value = match[0];
    showHint(data.text.opening, false);
    location.href = "cs2clutchez://" + match[0];
  });
})();
